import localFont from 'next/font/local'
import Header from '@/components/layout/Header'
import Footer from '@/components/layout/Footer'
import '@/styles/reset.css'
import '@/styles/variables.css'
import '@/styles/global.css'

// Point each src at your installed font file (paths are relative to this file)
const title = localFont({ src: '../fonts/YourRansomFont.woff2', variable: '--font-title' })
const display = localFont({ src: '../fonts/YourBlockFont.woff2', variable: '--font-display' })
const serif = localFont({
  src: [
    { path: '../fonts/YourSerifFont-Regular.woff2', weight: '400' },
    { path: '../fonts/YourSerifFont-Bold.woff2', weight: '700' },
  ],
  variable: '--font-serif',
})
const graffiti = localFont({ src: '../fonts/YourGraffitiFont.woff2', variable: '--font-graffiti' })

const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || 'http://localhost:3000'

export const metadata = {
  metadataBase: new URL(siteUrl),
  title: {
    default: 'Remember Us - Creative Project Showcase',
    template: '%s | Remember Us',
  },
  description: '4th year creative project showcase: AI + IM, Animations, Games, and Narrative & Visual Design.',
  openGraph: {
    siteName: 'Remember Us',
    type: 'website',
  },
}

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      <body className={`${title.variable} ${display.variable} ${serif.variable} ${graffiti.variable}`}>
        <Header />
        <main className="container">{children}</main>
        <Footer />
      </body>
    </html>
  )
}
